/* Design-only state machine. No backend, model calls, credential storage or external writes. */
const $ = (selector) => document.querySelector(selector);
const esc = (value) => String(value).replace(/[&<>"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {
  search:'m21 21-4.5-4.5M19 11a8 8 0 1 1-16 0 8 8 0 0 1 16 0',
  plus:'M12 5v14M5 12h14', arrow:'M12 19V5m-5 5 5-5 5 5',
  chat:'M4 4h16v12H8l-4 4V4', close:'m6 6 12 12M6 18 18 6',
  inbox:'M4 4h16v16H4V4m0 9h5l1 3h4l1-3h5',
  file:'M6 3h8l4 4v14H6V3m8 0v5h4M9 12h6m-6 4h6',
  clock:'M12 7v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
  plug:'M8 3v5m8-5v5M6 8h12v3a6 6 0 0 1-12 0V8m6 9v4',
  settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8m0-5v2m0 14v2M3 12h2m14 0h2M5.6 5.6 7 7m10 10 1.4 1.4m0-12.8L17 7M7 17l-1.4 1.4',
  computer:'M3 4h18v13H3V4m5 17h8m-4-4v4',
  panel:'M3 4h18v16H3V4m11 0v16', check:'m5 12 4 4L19 6',
  edit:'m4 16 11-11 4 4L8 20H4v-4m9-9 4 4', link:'m9 15 6-6M8 16l-2 2a3 3 0 0 1-4-4l5-5a3 3 0 0 1 4 0m2 0 2-2a3 3 0 0 1 4 4l-5 5a3 3 0 0 1-4 0',
  chevron:'m9 5 7 7-7 7', download:'M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5',
  group:'M9 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8M2 21v-2a7 7 0 0 1 14 0v2m1-16a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 4v2',
  book:'M4 3h16v18H4V3m4 0v18m4-13h5m-5 4h5', paperclip:'m8 12 6-6a3 3 0 0 1 4 4l-8 8a5 5 0 0 1-7-7l9-9',
  stop:'M6 6h12v12H6V6', menu:'M4 6h16M4 12h16M4 18h16',
};
const icon = (name) => `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name] || paths.chat}"/></svg>`;
const btn = (action, text, style = '', extra = '') => `<button type="button" data-action="${action}" class="button ${style}" ${extra}>${text}</button>`;
const ibtn = (action, name, label) => `<button type="button" class="icon-button" data-action="${action}" title="${label}" aria-label="${label}">${icon(name)}</button>`;
const bots = [
  {id:'research',name:'研究助理',initial:'研',role:'跟进产品与技术，交付有来源的判断。',runtime:'内置 Agent · 自有 API',sub:'研究简报已就绪',status:'待处理'},
  {id:'dev',name:'开发助理',initial:'码',role:'检查源码、复现问题、实现并验证变更。',runtime:'Codex · 本机账号',sub:'正在检查测试结果',status:'工作中'},
  {id:'daily',name:'日常助理',initial:'日',role:'整理每日信息，帮我安排持续工作。',runtime:'Claude Code · 本机账号',sub:'下次简报：明天 09:00',status:'空闲'},
];
const state = {
  active:'research',page:'chat',panel:innerWidth >= 1130 ? 'artifact' : null,profileTab:'role',connectionTab:'apps',
  task:'approval',action:'pending',actionVersion:1,approvedArtifactRevision:null,draftTitle:'Personal Agent 产品研究',draftBody:'从 Grok Bot 的长期助理、持久工作环境和定时工作，梳理本产品的一期设计与实现边界。',
  groups:[{id:'product',name:'产品研究',initial:'组',role:'研究助理负责资料，开发助理核对源码。',runtime:'2 位助理 · 主负责人：研究助理',sub:'资料收集 → 源码评估',status:'协作中'}],
  drafts:{},messages:{},attached:{},artifactVersion:1,online:true,takeover:false,skillSaved:false,routines:[{id:1,name:'工作日技术简报',owner:'日常助理',schedule:'weekdays',time:'09:00',timezone:'Asia/Shanghai',enabled:true}],
  memory:'研究报告优先引用官方资料，明确区分事实、推断和未验证项。',memoryEnabled:true,apps:{Notion:true,GitHub:true,'日历':false},notification:'仅新成果、异常和待处理',mobileMenu:false,
};
const taskByBot = {research:'approval',dev:'working',daily:'idle'};
Object.defineProperty(state,'task',{get(){return taskByBot[this.active] || 'idle';},set(value){taskByBot[this.active]=value;}});
const bot = () => [...bots,...state.groups].find(b => b.id === state.active) || bots[0];
let toastTimer;
let lastFocus;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3600);}
function rememberDraft(){const input=$('#message-input');if(input)state.drafts[state.active]=input.value;}
function nav(action,label,name,active=false,tail=''){return `<button class="nav-button ${active?'active':''}" data-action="${action}">${icon(name)}<span>${label}</span>${tail}</button>`;}
function botRow(b){let sub=b.sub;let status=b.status;if(b.id==='research'){status=taskLabel(taskByBot.research);sub=taskByBot.research==='approval'?'研究简报已就绪':status;}return `<button class="bot-button ${state.page==='chat'&&state.active===b.id?'active':''}" data-action="bot:${b.id}" aria-current="${state.page==='chat'&&state.active===b.id?'page':'false'}"><span class="avatar">${esc(b.initial)}</span><span class="fill"><span class="bot-name">${esc(b.name)}</span><span class="bot-sub" style="display:block">${esc(sub)}</span></span>${status==='空闲'?'':'<span class="bot-dot" title="'+esc(status)+'"></span>'}</button>`;}
function sidebar(){return `<aside class="sidebar ${state.mobileMenu?'mobile-open':''}" aria-label="主导航"><div class="brand"><span class="mark">✳</span>个人空间</div>${nav('search','搜索','search',false,'<span class="key">⌘ K</span>')}${nav('new','新建','plus',false,'<span class="key">⌘ N</span>')}${nav('page:attention','待处理','inbox',state.page==='attention',state.action==='pending'?'<span class="count">1</span>':'')}<div class="nav-label">助理 ${ibtn('new-bot','plus','创建助理')}</div>${bots.map(botRow).join('')}<div class="nav-label">工作组 ${ibtn('new-group','plus','创建工作组')}</div>${state.groups.map(botRow).join('')}<div class="nav-bottom">${nav('page:library','资料库','file',state.page==='library')}${nav('page:routines','定时工作','clock',state.page==='routines')}${nav('page:connections','应用与连接','plug',state.page==='connections')}<div class="account"><span class="avatar">SM</span><div class="fill">我的工作空间<small><span class="dot ${state.online?'':'off'}"></span>${state.online?'本机执行 · 已连接':'执行设备离线'}</small></div>${ibtn('settings','settings','账户与设置')}</div></div></aside>`;}
function taskLabel(value=state.task){return {approval:'需要你处理',working:'工作中',queued:'已接收',review:'待验收',completed:'已完成',stopped:'已停止',offline:'等待执行设备',denied:'草稿已保留',idle:'空闲'}[value] || value;}
function header(){const b=bot();const title=state.page==='chat'?b.name:({attention:'待处理',library:'资料库',routines:'定时工作',connections:'应用与连接'}[state.page]);return `<header class="chat-header"><div class="row">${ibtn('mobile-menu','menu','打开导航').replace('class="icon-button"','class="icon-button mobile-menu"')}${state.page==='chat'?'<span class="avatar">'+esc(b.initial)+'</span>':''}<div><h2>${esc(title)}</h2><div class="subtitle">${state.page==='chat'?`<span class="dot ${state.online?'':'off'}"></span>${state.online?'这台 Mac':'Mac 离线'} · ${esc(b.runtime)}`:'个人空间 · 所有助理'}</div></div></div><div class="header-tools">${state.page==='chat'?btn('panel:computer',icon('computer')+'工作环境','quiet')+ibtn('panel:profile','panel','助理资料'):''}<select id="scenario" class="scenario-select" aria-label="切换演示场景"><option value="">切换场景</option><option value="approval">成果与审批</option><option value="working">执行中补充</option><option value="offline">设备离线</option><option value="first">首次使用</option></select></div></header>`;}
function speaker(text){return `<div class="speaker"><span class="mini-mark">✳</span>${esc(bot().name)}<time>10:24</time></div><div class="message-body">${text}</div>`;}
function artifactCard(){return `<button class="artifact-card" data-action="panel:artifact"><span class="file-icon">${icon('file')}</span><span class="fill"><h3>下一代个人助理 · 研究简报</h3><small>Markdown · v${state.artifactVersion} · 附来源与设计建议</small></span>${icon('chevron')}</button>`;}
function approvalCard(){if(state.action!=='pending')return `<div class="receipt">${icon('check')} ${state.action==='approved'?'已批准动作 v'+state.actionVersion+' · 成果 v'+state.approvedArtifactRevision+' · 模拟回执 #D-1024':'暂不写入 · 草稿与本地成果已保留'}<div class="muted" style="font-size:10px;margin-top:4px">这是一条场景回执，没有向外部服务发送内容。</div></div>`;return `<section class="approval" aria-label="写入草稿审批"><div class="approval-top">${icon('inbox')}需要你确认<span class="fill"></span><span class="pill">动作 v${state.actionVersion}</span></div><div class="approval-content"><h3>把研究简报保存到 Notion</h3><p>只在你的私人研究空间创建草稿，不公开发布。你可以先改标题和摘要。</p><div class="approval-details"><span>目标</span><span>Notion / 私人研究 / 产品观察</span><span>标题</span><span>${esc(state.draftTitle)}</span><span>内容</span><span>研究简报 v${state.artifactVersion} · ${esc(state.draftBody)}</span><span>权限</span><span>仅本次创建 · 参数改变后重新确认</span></div><div class="approval-footer">${btn('approve','批准这一版','primary')}${btn('edit-draft',icon('edit')+'编辑草稿')}${btn('deny','暂不写入','quiet')}</div></div></section>`;}
function initialMessages(){if(state.active==='research'&&['working','queued'].includes(state.task))return `<div class="date">今天 · 修订中的工作</div><article class="message user"><div class="user-bubble">继续研究，补充实现边界并修订现有成果。</div></article><article class="message">${speaker('<p>'+ (state.task==='queued'?'请求已经接收，等待执行器认领。':'正在处理补充要求。可以继续调整方向，也可以停止当前执行。') +'</p><p class="muted">当前为场景模拟，尚未形成新的成果版本。</p>')}</article>`;if(state.active==='research')return `<div class="date">今天 · 10 月 27 日 <span class="muted">/ 示例对话</span></div><article class="message user"><div class="user-bubble">帮我研究 Grok Bot 的核心体验，结合现有源码形成产品简报。整理好后放到 Notion，写入前让我确认。</div></article><article class="message">${speaker(`<p>简报已整理好。最值得借鉴的是<strong>长期负责工作的助理</strong>，以及从一次委托延伸到工具使用、成果修订和定时工作的完整流程。</p><p>我把产品判断、交互和实现边界分开记录，方便接下来直接进入设计。</p><div class="source-row"><a class="source-chip" href="https://docs.x.ai/grok-bot/overview" target="_blank" rel="noopener"><i>↗</i> Grok Bot</a><a class="source-chip" href="https://docs.x.ai/grok-bot/computer-and-apps" target="_blank" rel="noopener"><i>↗</i> 工作环境</a><a class="source-chip" href="https://docs.x.ai/grok-bot/skills-routines-and-automations" target="_blank" rel="noopener"><i>↗</i> 技能与定时工作</a></div><details class="trace"><summary>查看工作过程 · 3 个阶段</summary><p>读取官方功能说明 → 对照源码已有对象 → 整理设计建议。此处为预设演示轨迹，不是实际执行日志。</p></details>${artifactCard()}${approvalCard()}`)}</article>`;
  if(state.active==='dev')return `<div class="date">今天 · 示例对话</div><article class="message user"><div class="user-bubble">检查个人任务查询是否包含 DM，并给出最小改动建议。</div></article><article class="message">${speaker('<p>现有频道任务列表排除了 DM 和 thread。建议保留它的语义，另增个人查询，按当前用户的会话可见性读取。</p><details class="trace" open><summary>当前工作 · 源码检查</summary><p>taskService → 个人读模型 → 权限与分页验证。这里展示执行中的交互状态。</p></details>'+btn('advance','推进演示：提交检查报告','primary'))}</article>`;
  if(state.groups.some(g=>g.id===state.active))return `<div class="date">工作组 · 示例协作</div><article class="message user"><div class="user-bubble">@研究助理 负责产品机制，@开发助理 核对源码；由研究助理汇总，不发布。</div></article><article class="message">${speaker('<p>两条工作分别有负责人，汇总仍回到这段对话。</p><div class="detail-row"><strong>研究助理 → 产品机制</strong><p>资料与结论，交付带来源的简报。</p></div><div class="detail-row"><strong>开发助理 → 源码评估</strong><p>返回可复用对象与缺口；不修改源码。</p></div><div class="info-box">组内只展示脱敏状态；敏感审批回到用户可见的原任务。</div>')}</article>`;
  return `<div class="date">今天 · 示例对话</div><article class="message">${speaker('<p>这段工作还没有开始。交给我一个目标、相关资料，以及你期望的结果。</p>'+btn('page:routines',icon('clock')+'查看定时工作'))}</article>`;
}
function chat(){const busy=['working','queued'].includes(state.task);const relevant=state.active==='research';return `${relevant?`<div class="task-strip">${icon(state.task==='offline'?'computer':'clock')}<strong>竞品研究与产品简报</strong><span class="pill">${taskLabel()}</span><span class="progress">${state.task==='approval'?'成果已生成 · 写入待确认':'目标明确 · 过程可追溯'}</span>${ibtn('task-detail','chevron','查看任务详情')}</div>`:''}<div class="transcript"><div class="conversation">${initialMessages()}${(state.messages[state.active]||[]).map(m=>m.who==='user'?`<article class="message user"><div class="user-bubble">${esc(m.text)}</div></article>`:`<article class="message">${speaker('<p>'+esc(m.text)+'</p>')}</article>`).join('')}${relevant&&state.task==='offline'?`<div class="info-box"><strong>这台 Mac 当前不可用</strong><p>保留任务和草稿，等待原设备恢复。不会自动把文件送到其他电脑。</p><div style="margin-top:10px">${btn('reconnect','演示：设备恢复','primary')}</div></div>`:''}${relevant&&['queued','working'].includes(state.task)?`<div class="info-box">${state.task==='queued'?'任务已接收，尚未宣称开始执行。':'正在整理输入与修订成果。'} ${btn('advance',state.task==='queued'?'推进演示：开始执行':'推进演示：完成成果','quiet')}</div>`:''}</div></div><div class="composer-wrap"><form id="composer" class="composer">${state.attached[state.active]?'<span class="context-tag">'+esc(state.attached[state.active])+' '+ibtn('remove-attachment','close','移除示例附件')+'</span>':''}<textarea id="message-input" aria-label="发送给助理的消息" placeholder="${busy?'补充要求，或调整当前工作的方向…':'交代一件事，或继续这段工作…'}" rows="2">${esc(state.drafts[state.active]||'')}</textarea><div class="composer-bottom"><div class="composer-actions">${ibtn('attach','paperclip','添加示例附件')}${btn('mention','@ 应用','quiet')}${btn('skill-picker','/ 技能','quiet')}</div><div class="row">${busy?btn('stop',icon('stop')+'停止','quiet'):''}<button type="submit" class="send-button" aria-label="发送消息">${icon('arrow')}</button></div></div></form><p class="composer-help">${busy?'补充按运行时能力送达 · ':''}Enter 发送 · Shift Enter 换行 · 所有执行为交互演示</p></div>`;}
function artifactPanel(){return `<div class="row between" style="margin-bottom:15px"><span class="label">研究简报</span><select id="artifact-version" class="version-select" aria-label="成果版本">${Array.from({length:state.artifactVersion},(_,i)=>`<option value="${i+1}" ${i+1===state.artifactVersion?'selected':''}>v${i+1}${i+1===state.artifactVersion?' · 最新':''}</option>`).join('')}</select></div><div class="document"><div class="label">FIELD NOTES / PERSONAL AGENTS</div><h1>让助理<br>长期负责一件事</h1><p style="font-size:9px">产品研究 · 2026.10.27 · 示例成果</p><hr><p>从一段自然对话出发，连起工作环境、可检查的成果与持续执行的方法。</p><h3>三个设计决定</h3><div class="doc-point"><b>01</b><p>用有职责的助理组织工作，保留背景与修订历史。</p></div><div class="doc-point"><b>02</b><p>把连接、接管与审批放在任务发生的位置。</p></div><div class="doc-point"><b>03</b><p>一次成功先保存为技能，再成为定时工作。</p></div><hr><p style="font-size:9px">实现边界：本机睡眠不能承诺后台继续；本地Agent能力逐项验证。</p><p id="version-note" style="font-size:9px;margin-top:12px">版本 v${state.artifactVersion} · 保留来源与验收范围</p></div><div class="metadata"><div class="row"><span>来源任务</span><div>竞品研究与产品简报</div></div><div class="row"><span>保存位置</span><div>这台 Mac / 受管工作目录</div></div><div class="row"><span>验证范围</span><div>示例结构；未由 Agent 实际生成</div></div></div><div class="inspector-actions">${btn('export',icon('download')+'导出示例')}${btn('save-skill',icon('book')+(state.skillSaved?'查看技能':'保存为技能'))}${btn('new-routine',icon('clock')+'定时再做')}${state.task==='review'?btn('accept-result','验收并结束任务','primary'):''}</div>`;}
function computerPanel(){return `<span class="label">执行位置</span><h2 style="margin-top:7px">这台 Mac</h2><p style="font-size:11px;color:var(--muted);margin-top:5px"><span class="dot ${state.online?'':'off'}"></span>${state.online?'已连接':'离线'} · ${esc(bot().runtime)}</p><div class="computer-frame"><div class="computer-toolbar"><span class="window-dot"></span><span class="window-dot"></span><span class="window-dot"></span><span style="margin-left:6px">受管浏览器 · 场景预览</span></div><div class="fake-page"><div class="label" style="font-size:7px">NOTION / PRIVATE WORKSPACE</div><h3>${state.takeover?'等待你完成登录':'产品观察'}</h3>${state.takeover?'<p>敏感输入在真实产品中由安全接管界面处理。此原型不接收密码。</p>':'<div class="fake-line"></div><div class="fake-line" style="width:80%"></div><div class="fake-line" style="width:65%"></div>'}</div></div><div class="info-box">${state.takeover?'你正在控制浏览器，助理已暂停输入。':'预览不是实时屏幕。这是用于评审接管流程的模拟场景。'}</div>${btn(state.takeover?'handoff':'takeover',state.takeover?'我已完成，交还助理':'接管演示',state.online?'primary':'',state.online?'':'disabled')}<div class="section-title">工作环境</div><div class="detail-row">目录<p>受管目录 / personal-research</p></div><div class="detail-row">应用账户<p>Notion · 私人空间；仅授权的助理可使用</p></div><div class="detail-row">运行模式<p>平台可控工具；本地原生 Agent 的权限另行检查</p></div><div class="detail-row">关闭与睡眠<p>窗口关闭后后台继续；Mac 睡眠时等待设备</p></div><div style="margin-top:18px">${btn(state.online?'offline':'reconnect',state.online?'演示设备离线':'演示设备恢复','quiet')}</div>`;}
function profilePanel(){const b=bot();let content='';if(state.profileTab==='role')content=`<div class="row"><span class="avatar">${esc(b.initial)}</span><div><h2>${esc(b.name)}</h2><small>长期职责 · 可随工作调整</small></div></div><div class="section-title">职责</div><p style="font-size:12px;line-height:1.9">${esc(b.role)}</p><div class="section-title">执行设置</div><div class="detail-row">这台 Mac<p>${esc(b.runtime)}</p></div><div class="detail-row">工作历史<p>竞品研究与产品简报 · ${taskLabel()}</p></div><div class="inspector-actions">${btn('edit-bot','编辑助理')}${btn('page:connections','检查执行配置')}</div>`;
  if(state.profileTab==='memory')content=`<span class="label">平台记忆 · ${state.memoryEnabled?'启用':'已停用'}</span><div class="detail-row"><h3>${esc(state.memory)}</h3><p>来源：你明确保存的偏好 · 作用于研究助理</p><p>原生 Agent 自有记忆需要在原环境管理。</p></div><div class="inspector-actions">${btn('edit-memory','更正')}${btn('toggle-memory',state.memoryEnabled?'停用':'恢复启用')}</div>`;
  if(state.profileTab==='skills')content=`<div class="detail-row"><h3>${state.skillSaved?'有来源的产品研究':'尚未保存平台技能'}</h3><p>${state.skillSaved?'v1 · 输入：主题与资料范围 · 需检查来源和边界':'完成并验收一次工作，再保存做法。'}</p></div>${btn('save-skill',state.skillSaved?'查看技能版本':'从本次成果保存','primary')}<div class="section-title">本机技能</div><p style="font-size:11px;color:var(--muted)">真实产品按 runtime 扫描来源。本原型不读取本地技能目录。</p>`;
  if(state.profileTab==='routines')content=`${state.routines.map(r=>`<div class="detail-row"><h3>${esc(r.name)}</h3><p>${esc(r.owner)} · ${r.time} · ${r.enabled?'已启用':'已暂停'}</p></div>`).join('')}<div style="margin-top:16px">${btn('new-routine','添加定时工作')}</div>`;
  return `<div class="tabs" role="tablist" aria-label="助理资料">${[['role','职责'],['memory','记忆'],['skills','技能'],['routines','定时']].map(([id,label])=>`<button role="tab" aria-selected="${state.profileTab===id}" data-action="profile:${id}" class="${state.profileTab===id?'active':''}">${label}</button>`).join('')}</div>${content}`;
}
function inspector(){if(!state.panel||state.page!=='chat')return '';return `<aside class="inspector" aria-label="工作检查区"><div class="inspector-header"><span>${{artifact:'成果预览',computer:'工作环境',profile:'助理资料'}[state.panel]}</span>${ibtn('close-panel','close','关闭检查区')}</div><div class="inspector-content">${state.panel==='artifact'?artifactPanel():state.panel==='computer'?computerPanel():profilePanel()}</div></aside>`;}
function attentionPage(){return `<div class="page-title"><h1>需要你处理</h1><p>决定、连接与接管，回到它们发生的那段工作。</p></div>${state.action==='pending'?`<div class="list-row"><span class="avatar">${icon('inbox')}</span><div class="fill"><h3>确认写入研究简报</h3><p>研究助理 · Notion / 私人研究 · 动作 v${state.actionVersion}</p></div>${btn('return-approval','查看并处理','primary')}</div>`:'<div class="blank-state">'+icon('check')+'<h2>暂时没有待处理事项</h2><p>需要你的决定时，助理会在原对话里找你。</p></div>'}<div class="info-box">成果验收与权限审批分别记录。没有新问题时，这里保持安静。</div>`;}
function libraryPage(){return `<div class="page-title"><h1>留下的工作</h1><p>可打开、可修订，也能找到它的来处。</p></div><div class="list-row"><span class="file-icon">${icon('file')}</span><div class="fill"><h3>下一代个人助理 · 研究简报</h3><p>研究助理 · Markdown · v${state.artifactVersion} · 这台 Mac</p></div>${btn('open-library-artifact','打开')}</div><div class="info-box">本机成果在其他设备不会自动可读。上传或分享是独立操作，需明确选择。</div>`;}
function routinesPage(){return `<div class="page-title row between"><div><h1>定时工作</h1><p>把确认过的方法，交给助理持续负责。</p></div>${btn('new-routine',icon('plus')+'新建','primary')}</div>${state.routines.map(r=>`<div class="list-row"><span class="avatar">${icon('clock')}</span><div class="fill"><h3>${esc(r.name)} <span class="pill">${r.enabled?'已启用':'已暂停'}</span></h3><p>${esc(r.owner)} · ${r.schedule==='weekdays'?'工作日':r.schedule==='weekly'?'每周二':'每天'} ${r.time} · ${r.timezone}</p><p>${r.enabled?'下次：'+nextRuns(r)[0]:'下次运行已暂停'}</p></div>${btn('routine-history:'+r.id,'历史','quiet')}${btn('routine-toggle:'+r.id,r.enabled?'暂停':'恢复')}</div>`).join('')}<div class="info-box"><strong>默认安静运行</strong><br>仅通知新成果、需要处理与持续失败。设备离线时记录等待或错过，不宣称按时完成。</div>`;}
function connectionsPage(){let rows='';if(state.connectionTab==='apps')rows=Object.entries(state.apps).map(([name,connected])=>`<div class="list-row"><span class="avatar">${name.slice(0,1)}</span><div class="fill"><h3>${name}</h3><p>${connected?'示例连接 · 已授权研究助理':'尚未连接 · 需要时从任务内继续'}</p></div>${btn('connect:'+name,connected?'管理':'连接')}</div>`).join('');
  if(state.connectionTab==='agents')rows=['Codex','Claude Code','内置 Agent'].map((name,i)=>`<div class="list-row"><span class="avatar">${icon('computer')}</span><div class="fill"><h3>${name}</h3><p>${i===2?'自有 API · 工具能力需独立检查':'已发现 → 已认证 → 真实执行（演示状态）'}</p></div>${btn('agent-config:'+name,'检查配置')}</div>`).join('');
  if(state.connectionTab==='api')rows=`<div class="list-row"><span class="avatar">API</span><div class="fill"><h3>我的模型连接</h3><p>OpenAI-compatible · 这台 Mac · 凭证隐藏</p></div>${btn('api-config','配置')}</div><div class="info-box">模型连接与 Agent 运行时是不同对象。能列出模型，不等于工具调用与实际任务已经可用。</div>`;
  if(state.connectionTab==='devices')rows=`<div class="list-row"><span class="avatar">${icon('computer')}</span><div class="fill"><h3>这台 Mac</h3><p>${state.online?'在线':'离线'} · 本地执行 · 睡眠影响后台工作</p></div>${btn(state.online?'offline':'reconnect',state.online?'演示离线':'演示恢复')}</div><div class="info-box">尚未配置常在线节点。这里不会用“本机已连接”承诺合盖后继续。</div>`;
  return `<div class="page-title"><h1>连接你的工作方式</h1><p>应用负责访问服务，Agent 负责执行；设备和模型分别配置。</p></div><div class="settings-nav">${[['apps','应用'],['agents','Agent'],['api','模型 API'],['devices','设备']].map(([id,label])=>`<button data-action="connection-tab:${id}" class="${state.connectionTab===id?'active':''}">${label}</button>`).join('')}</div>${rows}`;
}
function render(forceEnd=false){const before=$('.transcript');const oldTop=before?.scrollTop||0;const atEnd=!before||before.scrollHeight-before.clientHeight-oldTop<80;$('#app').innerHTML=sidebar()+`<div class="workbench"><main class="main">${header()}${state.page==='chat'?chat():`<div class="page-scroll"><div class="page-content">${({attention:attentionPage,library:libraryPage,routines:routinesPage,connections:connectionsPage}[state.page])()}</div></div>`}</main>${inspector()}</div>`;const after=$('.transcript');if(after)after.scrollTop=forceEnd||atEnd?after.scrollHeight:oldTop;}
function switchBot(id){rememberDraft();state.active=id;state.page='chat';state.mobileMenu=false;state.panel=null;render(true);}
function closeDialog(){const overlay=$('.overlay');if(!overlay)return;$('#dialog-root').innerHTML='';if(lastFocus?.isConnected)lastFocus.focus();else $('#message-input')?.focus();}
function dialog(title,intro,body,wide=false){lastFocus=document.activeElement;$('#dialog-root').innerHTML=`<div class="overlay"><section class="dialog ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="dialog-header"><h2 id="dialog-title">${title}</h2>${ibtn('close-dialog','close','关闭弹窗')}</div><p class="intro">${intro}</p>${body}</section></div>`;setTimeout(()=>$('.dialog input:not([disabled]),.dialog textarea,.dialog button:not([data-action="close-dialog"])')?.focus(),0);}
const actionsRow=(label)=>`<div class="error" id="form-error" role="alert"></div><div class="dialog-actions">${btn('close-dialog','取消','quiet')}<button type="submit" class="button primary">${label}</button></div>`;
function newBotDialog(){dialog('创建一个助理','给它一份清晰的职责。执行配置继承你的默认设置。',`<form id="new-bot-form"><label for="bot-name">名称</label><input id="bot-name" name="name" placeholder="例如：论文助理" required maxlength="24"><label for="bot-role">长期负责什么</label><textarea id="bot-role" name="role" rows="3" placeholder="说明资料范围、交付要求，以及需要我决定的事情。" required></textarea><label for="bot-runtime">执行方式</label><select id="bot-runtime" name="runtime"><option>Codex · 本机账号</option><option>Claude Code · 本机账号</option><option>内置 Agent · 自有 API</option></select><p class="helper">这台 Mac · 配置能力在真实产品中逐项验证。</p>${actionsRow('创建并开始对话')}</form>`);}
function newRoutineDialog(){dialog('把这件事定时交给助理','计划以示例时间 2026-10-27 为锚点预览。原型不会创建真实调度。',`<form id="routine-form"><label for="routine-name">工作名称</label><input id="routine-name" name="name" value="有来源的产品研究" required><label for="routine-owner">负责助理</label><select id="routine-owner" name="owner">${bots.map(b=>`<option ${b.id===state.active?'selected':''}>${esc(b.name)}</option>`).join('')}</select><label for="routine-instruction">输入与完成要求</label><textarea id="routine-instruction" name="instruction" rows="2" required>跟进官方产品资料，更新研究简报；来源过期时标记失败，不写入外部服务。</textarea><div class="form-row"><div><label for="routine-schedule">重复</label><select id="routine-schedule" name="schedule"><option value="weekdays">每个工作日</option><option value="daily">每天</option><option value="weekly">每周二</option></select></div><div><label for="routine-time">时间</label><input id="routine-time" name="time" type="time" value="09:00" required></div></div><label for="routine-zone">时区</label><select id="routine-zone" name="timezone"><option>Asia/Shanghai</option><option>America/Los_Angeles</option><option>Europe/London</option></select><div class="info-box"><strong>接下来三次</strong><div id="next-runs" class="routine-dates"></div></div><div class="helper">节点：这台 Mac · 预算：每次最多 20 分钟 · 通知：仅新成果或异常 · 离线只补最近一次且不超过两小时</div><div class="dialog-actions">${btn('routine-test','试运行演示')}<button type="submit" class="button primary">保存并启用（模拟）</button></div><div class="error" id="form-error" role="alert"></div></form>`,true);previewRoutine();}
function zoneParts(date,zone){const p=new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(date);return Object.fromEntries(p.filter(x=>x.type!=='literal').map(x=>[x.type,Number(x.value)]));}
function nextRuns(r){const anchor=new Date('2026-10-27T02:00:00Z');const local=zoneParts(anchor,r.timezone);const [hour,minute]=r.time.split(':').map(Number);if(!Number.isFinite(hour)||!Number.isFinite(minute))return ['请选择有效时间'];const result=[];for(let i=0;i<30&&result.length<3;i++){const d=new Date(Date.UTC(local.year,local.month-1,local.day+i));const day=d.getUTCDay();if((r.schedule==='weekdays'&&(day===0||day===6))||(r.schedule==='weekly'&&day!==2))continue;const wall=Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),d.getUTCDate(),hour,minute);let utc=wall;for(let j=0;j<3;j++){const p=zoneParts(new Date(utc),r.timezone);utc+=wall-Date.UTC(p.year,p.month-1,p.day,p.hour,p.minute,p.second);}if(utc>anchor.getTime())result.push(new Intl.DateTimeFormat('zh-CN',{timeZone:r.timezone,month:'2-digit',day:'2-digit',weekday:'short',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(utc))+' · '+r.timezone);}return result;}
function previewRoutine(){const form=$('#routine-form');if(form){const r=Object.fromEntries(new FormData(form));$('#next-runs').innerHTML=nextRuns(r).map(x=>`<span>${esc(x)}</span>`).join('');}}
function apiDialog(){dialog('模型 API','展示配置与检测的交互；不接受、传输或保存真实凭证。',`<form id="api-form"><label for="api-protocol">协议</label><select id="api-protocol" name="protocol"><option>OpenAI-compatible</option><option>Anthropic Messages</option></select><label for="api-url">服务地址（示例）</label><input id="api-url" name="url" value="https://api.example.com/v1" type="url" required><label for="api-model">模型</label><input id="api-model" name="model" placeholder="输入模型 ID" value="my-model" required><label for="api-key">凭证</label><input id="api-key" type="password" placeholder="原型禁止填写真实 API key" disabled><p class="helper">真实产品由凭证服务加密保存；只向执行节点发受限引用。</p><div class="info-box" id="api-result">执行节点：这台 Mac。文本、工具调用、流式支持分别检测。</div><div class="dialog-actions">${btn('api-test','模拟检测')}<button type="submit" class="button primary">保存示例配置</button></div></form>`);}
function searchDialog(){dialog('搜索你的工作','定位助理、成果、技能与定时工作。',`<input id="search-input" class="search-input" aria-label="搜索内容" placeholder="搜索助理、工作和文件…"><div id="search-results"></div>`);searchResults('');$('#search-input').focus();}
function searchResults(q){const hits=[...bots.map(b=>({title:b.name,sub:b.role,action:'bot:'+b.id,type:'chat'})),{title:'下一代个人助理 · 研究简报',sub:'成果 · v'+state.artifactVersion,action:'open-library-artifact',type:'file'},...state.routines.map(r=>({title:r.name,sub:'定时工作 · '+r.owner,action:'page:routines',type:'clock'})),...(state.skillSaved?[{title:'有来源的产品研究',sub:'技能 · v1',action:'save-skill',type:'book'}]:[])].filter(h=>(h.title+h.sub).toLowerCase().includes(q.toLowerCase()));$('#search-results').innerHTML=hits.length?hits.map(h=>`<button class="search-hit" data-action="${h.action}">${icon(h.type)}<span>${esc(h.title)}<small>${esc(h.sub)}</small></span></button>`).join(''):'<p class="muted" style="font-size:12px;padding:20px 0">没有匹配对象。试试“研究”或“简报”。</p>';}
function saveSkillDialog(){dialog(state.skillSaved?'技能 · 有来源的产品研究':'保存这次做法','技能包含方法与边界，不包含账户凭证。确认后仅在本原型状态中启用。',`<div class="detail-row"><h3>有来源的产品研究 · v1</h3><p>输入：主题、官方资料、源码版本、交付格式</p></div><div class="detail-row"><h3>步骤与校验</h3><p>核实来源 → 分析机制 → 对照源码 → 给设计判断；区分事实、推断与未验证项。</p></div><div class="detail-row"><h3>执行边界</h3><p>外部写入前展示草稿；没有来源时说明缺口；本地成果须验证可打开。</p></div><div class="dialog-actions">${btn('confirm-skill',state.skillSaved?'保持启用':'确认并启用','primary')}</div>`);}
function connectDialog(name){const connected=state.apps[name];dialog(name+(connected?' · 连接管理':' · 应用连接'),'真实产品将转入服务的授权流程；此处只演示范围确认。',`<div class="detail-row"><h3>个人测试空间（示例）</h3><p>${name==='Notion'?'读取所选页面；经动作审批后创建草稿。':'读取所选仓库，不自动获得推送权限。'}</p></div><label class="check-row"><input type="checkbox" id="app-grant" checked>允许研究助理使用这项连接</label><p class="helper">凭证不出现在对话中。撤销后下一次工具调用即受阻。</p><div class="dialog-actions">${connected?btn('revoke:'+name,'撤销示例连接'):''}${btn('confirm-connect:'+name,connected?'保存范围':'连接演示','primary')}</div>`);}
function taskDialog(){dialog('竞品研究与产品简报','任务事实、执行状态与审批分别记录。',`<div class="detail-row"><h3>${taskLabel()}</h3><p>负责人：研究助理 · 执行：这台 Mac · 尝试 #1</p></div><div class="detail-row"><h3>完成条件</h3><p>有来源的研究简报；产品判断与源码边界明确；Notion写入须批准。</p></div><div class="detail-row"><h3>运行事实</h3><p>消息已接收 → 示例成果就绪 → ${state.action==='pending'?'等待写入确认':'动作已有决定'}。生产代码必须分别取得真实回执。</p></div><div class="dialog-actions">${btn('close-dialog','返回对话','primary')}</div>`);}
function handleAction(action){
  if(!action)return;
  if(action==='close-dialog'){closeDialog();return;}
  if(action==='mobile-menu'){state.mobileMenu=!state.mobileMenu;render();return;}
  if(action==='search'){searchDialog();return;}
  if(action==='new'){dialog('开始一段工作','继续找已有助理，或者为新的长期职责创建助理。',bots.map(b=>`<button class="choice" data-action="bot:${b.id}"><span class="avatar">${b.initial}</span><span><h3>${esc(b.name)}</h3><p>${esc(b.role)}</p></span></button>`).join('')+`<div class="dialog-actions">${btn('new-group',icon('group')+'创建工作组')}${btn('new-bot',icon('plus')+'创建助理','primary')}</div>`);return;}
  if(action==='new-bot'){newBotDialog();return;}
  if(action==='new-group'){dialog('创建工作组','选择共同负责一项结果的助理；由一位主负责人汇总。',`<form id="group-form"><label for="group-name">组名</label><input id="group-name" name="name" value="新项目" required>${bots.map((b,i)=>`<label class="check-row"><input name="members" type="checkbox" value="${b.id}" ${i<2?'checked':''}><span class="avatar">${b.initial}</span>${b.name}</label>`).join('')}${actionsRow('创建工作组')}</form>`);return;}
  if(action.startsWith('bot:')){closeDialog();switchBot(action.slice(4));return;}
  if(action.startsWith('page:')){closeDialog();rememberDraft();state.page=action.slice(5);state.mobileMenu=false;render();return;}
  if(action.startsWith('panel:')){rememberDraft();state.panel=action.slice(6);render();return;}
  if(action.startsWith('profile:')){state.profileTab=action.slice(8);render();return;}
  if(action==='close-panel'){state.panel=null;render();return;}
  if(action==='approve'){if(state.action!=='pending')return;if(!state.apps.Notion){connectDialog('Notion');return;}state.action='approved';state.approvedArtifactRevision=state.artifactVersion;state.task='review';render();toast('已批准动作 v'+state.actionVersion+'，显示模拟回执；未真实写入。');return;}
  if(action==='deny'){state.action='denied';state.task='denied';render();toast('草稿已保留，没有外部写入。');return;}
  if(action==='edit-draft'){dialog('编辑要写入的草稿','修改会产生新动作版本；只批准屏幕上确认的这一版。',`<form id="draft-form"><label for="draft-title">标题</label><input id="draft-title" name="title" value="${esc(state.draftTitle)}" required><label for="draft-body">摘要</label><textarea id="draft-body" name="body" rows="5" required>${esc(state.draftBody)}</textarea>${actionsRow('保存并重新确认')}</form>`);return;}
  if(action==='return-approval'){state.page='chat';state.active='research';state.panel=null;render();$('.approval')?.scrollIntoView({block:'center'});return;}
  if(action==='open-library-artifact'){closeDialog();state.page='chat';state.active='research';state.panel='artifact';render();return;}
  if(action==='export'){const text='# 让助理长期负责一件事\n\n交互原型示例成果，非Agent运行结果。\n\n1. 用固定职责组织工作。\n2. 在任务中连接、审批与接管。\n3. 从成功流程保存技能，再配置定时工作。\n';const url=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='personal-agent-design-example.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出标记为示例的 Markdown。');return;}
  if(action==='save-skill'){saveSkillDialog();return;}
  if(action==='confirm-skill'){state.skillSaved=true;closeDialog();state.panel='profile';state.profileTab='skills';render();toast('技能 v1 已在原型中启用。');return;}
  if(action==='new-routine'){newRoutineDialog();return;}
  if(action==='routine-test'){toast('试运行演示：会创建独立 Run，并经过同样审批；此原型未实际执行。');return;}
  if(action.startsWith('routine-toggle:')){const r=state.routines.find(x=>x.id===Number(action.split(':')[1]));r.enabled=!r.enabled;render();toast(r.enabled?'已恢复示例计划。':'已暂停未来运行，当前工作不受影响。');return;}
  if(action.startsWith('routine-history:')){const r=state.routines.find(x=>x.id===Number(action.split(':')[1]));dialog(esc(r.name)+' · 运行历史','示例记录，不代表后台已执行。','<div class="detail-row"><h3>10 月 27 日 · 有新成果</h3><p>Run #D-01 · 来源新鲜度已检查 · 通知一次</p></div><div class="detail-row"><h3>10 月 26 日 · 无变化</h3><p>Run #D-00 · 未发送通知</p></div><div class="detail-row"><h3>重启恢复</h3><p>同一计划时刻仅认领一次，外部结果未知时先核验。</p></div>');return;}
  if(action==='takeover'){state.takeover=true;state.panel='computer';render();toast('接管演示：控制租约交给你，Agent 输入暂停。');return;}
  if(action==='handoff'){state.takeover=false;render();toast('交还演示：检查页面后，助理继续当前工作。');return;}
  if(action==='offline'){state.online=false;state.task='offline';render();toast('演示设备离线：工作与草稿已保留。');return;}
  if(action==='reconnect'){state.online=true;state.task=state.action==='pending'?'approval':'review';render();toast('演示重连：补读事件，继续原任务。');return;}
  if(action==='task-detail'){taskDialog();return;}
  if(action==='accept-result'){state.task='completed';render();toast('任务已验收结束（模拟），成果与历史保留。');return;}
  if(action==='advance'){state.task=state.task==='queued'?'working':'review';if(state.task==='review'){state.artifactVersion++;(state.messages[state.active]||=[]).push({who:'bot',text:'演示完成：修订后的成果已作为新版本保留。真实实现需要验证文件和运行回执。'});}render();return;}
  if(action==='stop'){dialog('停止当前执行？','停止不撤销已完成的文件修改或外部动作。',`<p style="font-size:12px">真实产品先发停止请求，收到执行器回执后才变为已停止。此处演示确认后的状态。</p><div class="dialog-actions">${btn('close-dialog','继续工作')}${btn('confirm-stop','停止演示','primary')}</div>`);return;}
  if(action==='confirm-stop'){state.task='stopped';closeDialog();render();toast('已停止（场景模拟）。');return;}
  if(action==='attach'){state.attached[state.active]='产品资料.pdf · 示例附件';render();toast('只添加示例附件，不读取你的文件。');return;}
  if(action==='remove-attachment'){delete state.attached[state.active];render();return;}
  if(action==='mention'){dialog('引用应用','实际执行只使用授予当前助理的能力。',Object.entries(state.apps).map(([name,on])=>`<button class="choice" data-action="mention-app:${name}"><span class="avatar">${name[0]}</span><span><h3>${name}</h3><p>${on?'示例已连接':'尚未连接，可先检查范围'}</p></span></button>`).join(''));return;}
  if(action.startsWith('mention-app:')){const name=action.slice(12);if(!state.apps[name]){connectDialog(name);return;}rememberDraft();state.drafts[state.active]=(state.drafts[state.active]||'')+' @'+name+' ';closeDialog();render();$('#message-input').focus();return;}
  if(action==='skill-picker'){if(!state.skillSaved){saveSkillDialog();return;}rememberDraft();state.drafts[state.active]=(state.drafts[state.active]||'')+' /有来源的产品研究 ';render();$('#message-input').focus();return;}
  if(action.startsWith('connection-tab:')){state.connectionTab=action.slice(15);render();return;}
  if(action.startsWith('connect:')){connectDialog(action.slice(8));return;}
  if(action.startsWith('confirm-connect:')){const name=action.slice(16);state.apps[name]=Boolean($('#app-grant')?.checked);closeDialog();render();toast('示例连接范围已更新，未真实授权。');return;}
  if(action.startsWith('revoke:')){state.apps[action.slice(7)]=false;closeDialog();render();toast('示例连接已撤销。');return;}
  if(action==='api-config'){apiDialog();return;}
  if(action==='api-test'){$('#api-result').innerHTML='<strong>模拟探测结果</strong><br>地址格式通过 · 文本响应通过 · 工具与流式需独立验证<br>本原型没有发送任何网络请求。';return;}
  if(action.startsWith('agent-config:')){dialog(esc(action.slice(13))+' · 执行配置','以下是能力表达的设计示例，未检测本机程序。','<div class="detail-row"><h3>分层检查</h3><p>已发现 → 认证通过 → 真实任务通过，每步保存独立证据。</p></div><div class="detail-row"><h3>输入与恢复</h3><p>原生driver声明steer/排队、停止、session恢复，未知能力不默认启用。</p></div><div class="info-box">可信本地模式：平台无法逐项阻止不受控shell或浏览器行为。只有工具出口可控的运行模式才能强制执行平台审批。</div>');return;}
  if(action==='edit-memory'){dialog('更正这条记忆','仅更改平台记忆。原生 Agent 的历史不会被自动清理。',`<form id="memory-form"><label for="memory-content">内容</label><textarea id="memory-content" name="text" rows="4" required>${esc(state.memory)}</textarea><p class="helper">作用范围：研究助理 · 来源：用户更正 · 保存后旧版失效</p>${actionsRow('保存更正')}</form>`);return;}
  if(action==='toggle-memory'){state.memoryEnabled=!state.memoryEnabled;render();toast(state.memoryEnabled?'记忆已恢复。':'已停用，后续任务不再注入这条平台记忆。');return;}
  if(action==='edit-bot'){dialog('编辑助理','更改长期职责，不重写已有任务历史。',`<form id="edit-bot-form"><label for="edit-bot-name">名称</label><input id="edit-bot-name" name="name" value="${esc(bot().name)}" required><label for="edit-bot-role">职责</label><textarea id="edit-bot-role" name="role" required>${esc(bot().role)}</textarea>${actionsRow('保存')}</form>`);return;}
  if(action==='settings'){dialog('账户与设置','常用行为统一配置，执行身份与秘密单独管理。',`<div class="detail-row row between"><span>外观 · ${document.body.classList.contains('dark')?'深色':'浅色'}</span>${btn('theme','切换')}</div><div class="detail-row"><h3>通知</h3><p>${esc(state.notification)}；默认隐藏敏感正文</p></div><div class="detail-row"><h3>默认执行</h3><p>这台 Mac · 本地 Agent / 自有 API</p></div><div class="section-title">快捷键</div><div class="shortcuts"><span>搜索</span><span class="kbd">⌘ K</span><span>新建</span><span class="kbd">⌘ N</span><span>设置</span><span class="kbd">⌘ ,</span><span>关闭检查区 / 弹窗</span><span class="kbd">Esc</span></div><div class="dialog-actions">${btn('open-onboarding','查看首次使用')}</div>`);return;}
  if(action==='theme'){document.body.classList.toggle('dark');return;}
  if(action==='open-onboarding'){onboarding();return;}
}
function onboarding(){dialog('你的助理，按你的方式运行','先连通一种执行方式，再交给助理第一件有用的工作。',`<button class="choice" data-action="onboard-local"><span class="avatar">${icon('computer')}</span><span><h3>使用已有 Agent</h3><p>沿用 Codex / Claude Code 的本机账号与配置。</p></span>${icon('chevron')}</button><button class="choice" data-action="api-config"><span class="avatar">API</span><span><h3>使用模型 API</h3><p>配置自己的供应商、模型与执行节点。</p></span>${icon('chevron')}</button><div class="dialog-actions">${btn('close-dialog','稍后配置，先浏览','quiet')}</div>`);}
document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(target){const action=target.dataset.action;if(action==='onboard-local'){dialog('连接本机 Agent','程序发现、认证和实际执行是不同的检查。',`<div class="detail-row"><h3>Codex</h3><p>发现程序 → 认证状态 → 真实任务探测（场景示例）</p></div><div class="info-box">仅在真实检测完成后才能显示通过。本原型不会检查或启动本机程序。</div><div class="dialog-actions">${btn('new-bot','继续创建助理','primary')}</div>`);return;}handleAction(action);}if(event.target.classList.contains('overlay'))closeDialog();});
document.addEventListener('submit',event=>{event.preventDefault();const form=event.target;const data=Object.fromEntries(new FormData(form));
  if(form.id==='composer'){const text=$('#message-input').value.trim();if(!text)return;(state.messages[state.active]||=[]).push({who:'user',text});state.drafts[state.active]='';$('#message-input').value='';delete state.attached[state.active];(state.messages[state.active]||=[]).push({who:'bot',text:state.online?'已接收这条补充（模拟）。用“推进演示”查看执行与成果状态；没有真实调用 Agent。':'消息已保留为待执行（模拟），等待这台 Mac 恢复。'});state.task=state.online?'queued':'offline';render();$('.transcript').scrollTop=$('.transcript').scrollHeight;return;}
  if(form.id==='new-bot-form'){if(!data.name.trim()||!data.role.trim())return;const id='custom-'+Date.now();bots.push({id,name:data.name.trim(),initial:data.name.trim().slice(0,1),role:data.role,runtime:data.runtime,sub:'新助理 · 等待第一件工作',status:'空闲'});closeDialog();switchBot(id);toast('助理已在原型中创建，刷新会重置示例状态。');return;}
  if(form.id==='group-form'){const members=new FormData(form).getAll('members');if(members.length<2){$('#form-error').textContent='至少选择两位助理。';return;}const id='group-'+Date.now();state.groups.push({id,name:data.name,initial:'组',role:members.map(id=>bots.find(b=>b.id===id).name).join('、')+' 共同负责',runtime:members.length+' 位助理 · 第一位负责汇总',sub:'等待共同目标',status:'空闲'});closeDialog();switchBot(id);return;}
  if(form.id==='draft-form'){state.draftTitle=data.title;state.draftBody=data.body;state.actionVersion++;state.action='pending';closeDialog();render();toast('草稿已更新为动作 v'+state.actionVersion+'，需要重新确认。');return;}
  if(form.id==='routine-form'){state.routines.push({id:Date.now(),...data,enabled:true});closeDialog();state.page='routines';render();toast('已保存示例计划；原型不会实际调度。');return;}
  if(form.id==='api-form'){closeDialog();toast('示例配置已记录；未保存凭证或连接真实 API。');return;}
  if(form.id==='memory-form'){state.memory=data.text;state.memoryEnabled=true;closeDialog();render();toast('平台记忆已更正，旧版失效（模拟）。');return;}
  if(form.id==='edit-bot-form'){Object.assign(bot(),{name:data.name,role:data.role});closeDialog();render();return;}
});
document.addEventListener('input',event=>{if(event.target.id==='message-input')state.drafts[state.active]=event.target.value;if(event.target.id==='search-input')searchResults(event.target.value);if(event.target.closest('#routine-form'))previewRoutine();});
document.addEventListener('change',event=>{if(event.target.id==='scenario'){const value=event.target.value;if(value==='first'){onboarding();event.target.value='';return;}if(value){state.active='research';state.page='chat';state.task=value;state.online=value!=='offline';state.takeover=false;if(value==='approval')state.action='pending';state.panel=value==='offline'?'computer':null;render();}}if(event.target.id==='artifact-version')$('#version-note').textContent='正在查看版本 v'+event.target.value+' · 历史版本保留';if(event.target.closest('#routine-form'))previewRoutine();});
document.addEventListener('keydown',event=>{if(event.isComposing)return;if(event.key==='Escape'){if($('.overlay'))closeDialog();else{state.panel=null;state.mobileMenu=false;render();}return;}if((event.metaKey||event.ctrlKey)&&['k','n',',','b'].includes(event.key.toLowerCase())){event.preventDefault();const key=event.key.toLowerCase();if(key==='k')searchDialog();else if(key==='n')handleAction('new');else if(key===',')handleAction('settings');else{const side=$('.sidebar');side.style.display=side.style.display==='none'?'':'none';}return;}if(event.target.id==='message-input'&&event.key==='Enter'&&!event.shiftKey){event.preventDefault();$('#composer').requestSubmit();}if(event.key==='Tab'&&$('.dialog')){const elements=[...$('.dialog').querySelectorAll('button:not([disabled]),input:not([disabled]),textarea,select,a[href]')];const first=elements[0],last=elements.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
$('#theme-toggle').addEventListener('click',()=>document.body.classList.toggle('dark'));
render();
